    "declic_frequence": "ʿazīz-raḥīm (le Puissant-Miséricordieux, racines ع-ز-ز et ر-ح-م) revient huit fois comme refrain clôturant chaque récit. L'alliance des deux noms est le cœur théologique : la puissance qui châtie les dénégateurs est la MÊME qui fait miséricorde aux croyants. ʿizza sans raḥma serait tyrannie ; raḥma sans ʿizza, faiblesse. Le Dieu du Coran est indissociablement les deux — fort pour sauver, miséricordieux dans Sa force."
